def configure(original):
    c = deepcopy(original)
    if c['rules'].get('warm_child_copy'):
        return c, []
    nodes = {n['id']: n for n in c['nodes']}
    changed = []
    for key in graph(c, 'child'):
        n = nodes[key]
        if not n.get('text') or key in {'hp_city', 'work_city', 'work_age', 'work_experience', 'work_salary'}:
            continue
        old = n['text']
        if key in SCREENS:
            # Keep all original hyperlinks, including the career test.
            links = re.findall(r'\[[^\]]+\]\(https?://[^\s)]+\)', old)
            n['text'] = SCREENS[key] + ('\n\n' + '\n'.join(links) if links else '')
        else:
            intro = INTRO.get(key) or next((text for prefix, text in TOPICS if key.startswith(prefix)), None)
            if not intro:
                raise ValueError('Missing tailored introduction: ' + key)
            parts = old.split('\n\n', 1)
            n['text'] = parts[0] + '\n\n' + intro + ('\n\n' + parts[1] if len(parts) > 1 else '')
        changed.append(key)
    for key, text in UI.items():
        if key in c['ui']:
            c['ui'][key]['text'] = text
    nodes[c['start']]['buttons'] = [b for b in nodes[c['start']]['buttons']
        if b.get('values', {}).get('role') not in {'parent', 'candidate'}]
    c['rules']['child_only'] = True
    c['rules']['warm_child_copy'] = True
    return validate(c), changed
